<?php require __DIR__.'/config/bootstrap.php';
if($_SERVER['REQUEST_METHOD']==='POST'){ $s=$db->pdo()->prepare('INSERT INTO notes(title,body) VALUES(?,?)');$s->execute(array(trim($_POST['title']),trim($_POST['body']))); }
$rows=$db->pdo()->query('SELECT * FROM notes ORDER BY id DESC')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@3.4.1/dist/css/bootstrap.min.css"></head><body><div class="container"><p><a href="index.php">← Dashboard</a></p><h1>Private Notes</h1><form method="post"><input class="form-control" name="title" placeholder="Title" required><br><textarea class="form-control" name="body" rows="6" placeholder="Private note" required></textarea><br><button class="btn btn-primary">Save</button></form><hr><?php foreach($rows as $r):?><div class="panel panel-default"><div class="panel-heading"><strong><?=e($r['title'])?></strong></div><div class="panel-body"><pre><?=e($r['body'])?></pre></div></div><?php endforeach;?></div></body></html>
